def is_time_between(check_hhmm, start_hhmm, end_hhmm):
    def minutes(t):
        h, m = t.split(':')
        return int(h) * 60 + int(m)
    s, e, c = minutes(start_hhmm), minutes(end_hhmm), minutes(check_hhmm)
    window = set()
    end_adj = e if e > s else e + 1440
    for t in range(s, end_adj):
        window.add(t % 1440)
    return c in window

